#!/usr/bin/env perl
# -*- coding: utf-8 -*-

use strict;
use warnings;
use Getopt::Long;

# ============================================================
# Script: cluster_sa_split_reads.pl
#
# Purpose:
#   Cluster SA split-read deletion evidence generated by
#   extract_sa_split_reads.pl.
#
# Required parameters:
#   --conf      Config file
#   --input     SA split-read TSV from extract_sa_split_reads.pl
#   --outfile   PASS cluster summary output TSV file
#
# Output:
#   1. --outfile
#      PASS clusters only
#
#   2. failed cluster file, automatically derived from --outfile
#      Example:
#        FHOD3.sa_split_reads.clusters.tsv
#        -> FHOD3.sa_split_reads.failed_clusters.tsv
#
#   3. supporting reads file, automatically derived from --outfile
#      Example:
#        FHOD3.sa_split_reads.clusters.tsv
#        -> FHOD3.sa_split_reads.supporting_reads.tsv
#
# Clustering rule:
#   Only records satisfying all conditions are clustered:
#     1. Junction_Type == Deletion_Gap
#     2. SV_Chrom/SV_Start/SV_End are valid
#     3. SA_MAPQ >= MIN_MAPQ
#
#   A record belongs to the current cluster if:
#     same SV_Chrom
#     abs(record.SV_Start - median(cluster.SV_Start)) <= SA_SPLIT_CLUSTER_WINDOW
#     abs(record.SV_End   - median(cluster.SV_End))   <= SA_SPLIT_CLUSTER_WINDOW
#
# Config keys used:
#   MIN_MAPQ
#   SA_SPLIT_CLUSTER_WINDOW
#   SA_SPLIT_MIN_SUPPORT_READS
# ============================================================

my $conf    = "";
my $input   = "";
my $outfile = "";
my $help    = 0;

GetOptions(
    "conf=s"    => \$conf,
    "input=s"   => \$input,
    "outfile=s" => \$outfile,
    "help"      => \$help,
) or die usage();

if ($help) {
    print usage();
    exit 0;
}

die usage() unless $conf && $input && $outfile;

die "[ERROR] Config file not found: $conf\n" unless -s $conf;
die "[ERROR] Input file not found: $input\n" unless -s $input;

my %cfg = read_conf($conf);

my $min_mapq = get_conf_value(
    \%cfg,
    "MIN_MAPQ",
    20
);

my $cluster_window = get_conf_value(
    \%cfg,
    "SA_SPLIT_CLUSTER_WINDOW",
    20
);

my $min_support_reads = get_conf_value(
    \%cfg,
    "SA_SPLIT_MIN_SUPPORT_READS",
    5
);

die "[ERROR] MIN_MAPQ must be a non-negative integer\n"
    unless defined $min_mapq && $min_mapq =~ /^\d+$/;

die "[ERROR] SA_SPLIT_CLUSTER_WINDOW must be a non-negative integer\n"
    unless defined $cluster_window && $cluster_window =~ /^\d+$/;

die "[ERROR] SA_SPLIT_MIN_SUPPORT_READS must be a positive integer\n"
    unless defined $min_support_reads && $min_support_reads =~ /^\d+$/ && $min_support_reads > 0;

my $pass_cluster_out   = $outfile;
my $failed_cluster_out = derive_failed_clusters_outfile($outfile);
my $support_out        = derive_supporting_reads_outfile($outfile);

my @records = read_sa_split_records($input);

my @deletion_records = grep {
       $_->{Junction_Type} eq "Deletion_Gap"
    && $_->{SV_Chrom} ne "NA"
    && $_->{SV_Start} =~ /^\d+$/
    && $_->{SV_End}   =~ /^\d+$/
    && $_->{SA_MAPQ}  =~ /^\d+$/
    && $_->{SA_MAPQ} >= $min_mapq
} @records;

my $deletion_gap_all = scalar(grep {
       $_->{Junction_Type} eq "Deletion_Gap"
    && $_->{SV_Chrom} ne "NA"
    && $_->{SV_Start} =~ /^\d+$/
    && $_->{SV_End}   =~ /^\d+$/
} @records);

my $filtered_by_sa_mapq = $deletion_gap_all - scalar(@deletion_records);

my @clusters = cluster_records(
    records        => \@deletion_records,
    cluster_window => $cluster_window,
);

classify_clusters(
    clusters          => \@clusters,
    min_support_reads => $min_support_reads,
);

write_cluster_summary(
    clusters => \@clusters,
    output   => $pass_cluster_out,
    status   => "Pass",
);

write_cluster_summary(
    clusters => \@clusters,
    output   => $failed_cluster_out,
    status   => "Failed",
);

write_supporting_reads(
    clusters => \@clusters,
    output   => $support_out,
);

my $pass_n = scalar(grep { $_->{Cluster_Status} eq "Pass" } @clusters);
my $fail_n = scalar(@clusters) - $pass_n;

print STDERR "[INFO] SA split-read clustering finished\n";
print STDERR "[INFO] Config                    : $conf\n";
print STDERR "[INFO] Input                     : $input\n";
print STDERR "[INFO] PASS cluster output       : $pass_cluster_out\n";
print STDERR "[INFO] Failed cluster output     : $failed_cluster_out\n";
print STDERR "[INFO] Supporting reads output   : $support_out\n";
print STDERR "[INFO] MIN_MAPQ                  : $min_mapq\n";
print STDERR "[INFO] SA_SPLIT_CLUSTER_WINDOW   : $cluster_window\n";
print STDERR "[INFO] SA_SPLIT_MIN_SUPPORT_READS: $min_support_reads\n";
print STDERR "[INFO] Total input records       : " . scalar(@records) . "\n";
print STDERR "[INFO] Deletion_Gap records      : $deletion_gap_all\n";
print STDERR "[INFO] Filtered by SA_MAPQ       : $filtered_by_sa_mapq\n";
print STDERR "[INFO] Records for clustering    : " . scalar(@deletion_records) . "\n";
print STDERR "[INFO] Total cluster number      : " . scalar(@clusters) . "\n";
print STDERR "[INFO] PASS cluster number       : $pass_n\n";
print STDERR "[INFO] Failed cluster number     : $fail_n\n";

exit 0;

# ============================================================
# Subroutines
# ============================================================

sub usage {
    return <<"USAGE";
Usage:
  perl cluster_sa_split_reads.pl \\
      --conf conf/hcm_exondel.example.conf \\
      --input sample.sa_split_reads.tsv \\
      --outfile sample.sa_split_reads.clusters.tsv

Required:
  --conf STR      Config file
  --input STR     Input TSV generated by extract_sa_split_reads.pl
  --outfile STR   PASS cluster summary output TSV file

Input requirement:
  The input TSV must contain SA_MAPQ column.

Derived output:
  If --outfile ends with ".clusters.tsv":
      failed clusters file:
        ".clusters.tsv" -> ".failed_clusters.tsv"

      supporting reads file:
        ".clusters.tsv" -> ".supporting_reads.tsv"

Config keys:
  MIN_MAPQ
      Minimum SA_MAPQ required for split-read clustering.
      Default: 20

  SA_SPLIT_CLUSTER_WINDOW
      Maximum allowed breakpoint difference for clustering.
      Default: 20

  SA_SPLIT_MIN_SUPPORT_READS
      Minimum unique read names required for PASS.
      Default: 5

Example:
  perl bin/cluster_sa_split_reads.pl \\
      --conf conf/hcm_exondel.example.conf \\
      --input FHOD3.sa_split_reads.tsv \\
      --outfile FHOD3.sa_split_reads.clusters.tsv

USAGE
}

sub read_conf {
    my ($file) = @_;

    my %cfg;

    open my $fh, "<", $file
        or die "[ERROR] Cannot open config file: $file\n";

    while (my $line = <$fh>) {
        chomp $line;

        $line =~ s/\r$//;
        $line =~ s/^\s+//;
        $line =~ s/\s+$//;

        next if $line eq "";
        next if $line =~ /^#/;

        $line =~ s/\s+#.*$//;

        next unless $line =~ /^([A-Za-z0-9_.-]+)\s*=\s*(.*)$/;

        my $key = $1;
        my $val = $2;

        $val =~ s/^\s+//;
        $val =~ s/\s+$//;
        $val =~ s/^["']//;
        $val =~ s/["']$//;

        $cfg{$key} = $val;
    }

    close $fh;

    return %cfg;
}

sub get_conf_value {
    my ($cfg_ref, $key, $default) = @_;

    if (exists $cfg_ref->{$key} && defined $cfg_ref->{$key} && $cfg_ref->{$key} ne "") {
        return $cfg_ref->{$key};
    }

    return $default;
}

sub derive_failed_clusters_outfile {
    my ($outfile) = @_;

    my $failed_out = $outfile;

    if ($failed_out =~ /\.clusters\.tsv$/) {
        $failed_out =~ s/\.clusters\.tsv$/.failed_clusters.tsv/;
    }
    elsif ($failed_out =~ /\.tsv$/) {
        $failed_out =~ s/\.tsv$/.failed_clusters.tsv/;
    }
    else {
        $failed_out .= ".failed_clusters.tsv";
    }

    return $failed_out;
}

sub derive_supporting_reads_outfile {
    my ($outfile) = @_;

    my $support_out = $outfile;

    if ($support_out =~ /\.clusters\.tsv$/) {
        $support_out =~ s/\.clusters\.tsv$/.supporting_reads.tsv/;
    }
    elsif ($support_out =~ /\.tsv$/) {
        $support_out =~ s/\.tsv$/.supporting_reads.tsv/;
    }
    else {
        $support_out .= ".supporting_reads.tsv";
    }

    return $support_out;
}

sub read_sa_split_records {
    my ($file) = @_;

    open my $fh, "<", $file
        or die "[ERROR] Cannot open input file: $file\n";

    my $header = <$fh>;
    die "[ERROR] Empty input file: $file\n" unless defined $header;

    chomp $header;
    $header =~ s/\r$//;

    my @cols = split /\t/, $header;
    my %idx;

    for (my $i = 0; $i < @cols; $i++) {
        $idx{$cols[$i]} = $i;
    }

    my @required_cols = qw(
        Sample
        Scan_Mode
        Scan_Gene
        Scan_Region
        Read_Name
        Flag
        Primary_Chrom
        Primary_Start
        Primary_End
        Primary_CIGAR
        Primary_MAPQ
        Primary_Strand
        SA_Chrom
        SA_Start
        SA_End
        SA_CIGAR
        SA_MAPQ
        SA_Strand
        Left_Breakpoint
        Right_Breakpoint
        SV_Chrom
        SV_Start
        SV_End
        SV_Length
        Junction_Type
        SA_Tag
    );

    foreach my $col (@required_cols) {
        die "[ERROR] Required column '$col' not found in input file: $file\n"
            unless exists $idx{$col};
    }

    my @records;
    my $line_no = 1;

    while (my $line = <$fh>) {
        $line_no++;

        chomp $line;
        $line =~ s/\r$//;

        next if $line =~ /^\s*$/;

        my @f = split /\t/, $line, -1;

        my %r;
        foreach my $col (@required_cols) {
            my $v = defined $f[ $idx{$col} ] ? $f[ $idx{$col} ] : "NA";
            $v = "NA" if $v eq "";
            $r{$col} = $v;
        }

        $r{_line_no} = $line_no;

        push @records, \%r;
    }

    close $fh;

    return @records;
}

sub cluster_records {
    my %args = @_;

    my $records_ref    = $args{records};
    my $cluster_window = $args{cluster_window};

    my @records = @$records_ref;

    @records = sort {
        $a->{SV_Chrom} cmp $b->{SV_Chrom}
            ||
        $a->{SV_Start} <=> $b->{SV_Start}
            ||
        $a->{SV_End} <=> $b->{SV_End}
            ||
        $a->{Read_Name} cmp $b->{Read_Name}
    } @records;

    my @clusters;
    my @current;

    foreach my $r (@records) {
        if (!@current) {
            @current = ($r);
            next;
        }

        my $current_chr = $current[0]->{SV_Chrom};

        if ($r->{SV_Chrom} ne $current_chr) {
            push @clusters, build_cluster(\@current);
            @current = ($r);
            next;
        }

        my $median_start = median(map { $_->{SV_Start} } @current);
        my $median_end   = median(map { $_->{SV_End}   } @current);

        if (
            abs($r->{SV_Start} - $median_start) <= $cluster_window
            &&
            abs($r->{SV_End} - $median_end) <= $cluster_window
        ) {
            push @current, $r;
        }
        else {
            push @clusters, build_cluster(\@current);
            @current = ($r);
        }
    }

    if (@current) {
        push @clusters, build_cluster(\@current);
    }

    for (my $i = 0; $i < @clusters; $i++) {
        my $cluster_id = sprintf("SR_CLUSTER_%06d", $i + 1);
        $clusters[$i]->{Cluster_ID} = $cluster_id;

        foreach my $r (@{ $clusters[$i]->{records} }) {
            $r->{Cluster_ID} = $cluster_id;
        }
    }

    return @clusters;
}

sub build_cluster {
    my ($records_ref) = @_;

    my @records = @$records_ref;

    my @starts = map { $_->{SV_Start} } @records;
    my @ends   = map { $_->{SV_End}   } @records;

    my $cluster_start = int_median(@starts);
    my $cluster_end   = int_median(@ends);

    my $cluster_length = $cluster_end - $cluster_start + 1;
    $cluster_length = 0 if $cluster_length < 0;

    my %read_names;
    my %scan_genes;
    my %samples;
    my %primary_strand_count;
    my %sa_strand_count;

    foreach my $r (@records) {
        $read_names{ $r->{Read_Name} } = 1;
        $scan_genes{ $r->{Scan_Gene} } = 1;
        $samples{ $r->{Sample} } = 1;

        $primary_strand_count{ $r->{Primary_Strand} }++;
        $sa_strand_count{ $r->{SA_Strand} }++;
    }

    my $support_reads   = scalar(keys %read_names);
    my $support_records = scalar(@records);

    my $sv_start_min = min(@starts);
    my $sv_start_max = max(@starts);
    my $sv_end_min   = min(@ends);
    my $sv_end_max   = max(@ends);

    return {
        Cluster_ID           => "NA",
        Sample               => join(",", sort keys %samples),
        SV_Chrom             => $records[0]->{SV_Chrom},
        Cluster_Start        => $cluster_start,
        Cluster_End          => $cluster_end,
        Cluster_Length       => $cluster_length,
        SV_Start_Min         => $sv_start_min,
        SV_Start_Max         => $sv_start_max,
        SV_End_Min           => $sv_end_min,
        SV_End_Max           => $sv_end_max,
        Support_Reads        => $support_reads,
        Support_Records      => $support_records,
        Scan_Genes           => join(",", sort keys %scan_genes),
        Primary_Strand_Count => format_count_hash(\%primary_strand_count),
        SA_Strand_Count      => format_count_hash(\%sa_strand_count),
        Cluster_Status       => "NA",
        records              => \@records,
    };
}

sub classify_clusters {
    my %args = @_;

    my $clusters_ref      = $args{clusters};
    my $min_support_reads = $args{min_support_reads};

    foreach my $c (@$clusters_ref) {
        if ($c->{Support_Reads} < $min_support_reads) {
            $c->{Cluster_Status} = "LowSupport";
        }
        else {
            $c->{Cluster_Status} = "Pass";
        }

        foreach my $r (@{ $c->{records} }) {
            $r->{Cluster_Status} = $c->{Cluster_Status};
        }
    }
}

sub write_cluster_summary {
    my %args = @_;

    my $clusters_ref = $args{clusters};
    my $output       = $args{output};
    my $status       = $args{status};

    open my $out_fh, ">", $output
        or die "[ERROR] Cannot write cluster summary file: $output\n";

    print $out_fh join("\t", qw(
        Sample
        Cluster_ID
        SV_Chrom
        Cluster_Start
        Cluster_End
        Cluster_Length
        Support_Reads
        Support_Records
        Scan_Genes
        SV_Start_Range
        SV_End_Range
        Primary_Strand_Count
        SA_Strand_Count
        Cluster_Status
    )) . "\n";

    foreach my $c (@$clusters_ref) {
        if ($status eq "Pass") {
            next unless $c->{Cluster_Status} eq "Pass";
        }
        elsif ($status eq "Failed") {
            next if $c->{Cluster_Status} eq "Pass";
        }

        my $sv_start_range = $c->{SV_Start_Min} . "-" . $c->{SV_Start_Max};
        my $sv_end_range   = $c->{SV_End_Min}   . "-" . $c->{SV_End_Max};

        print $out_fh join("\t",
            $c->{Sample},
            $c->{Cluster_ID},
            $c->{SV_Chrom},
            $c->{Cluster_Start},
            $c->{Cluster_End},
            $c->{Cluster_Length},
            $c->{Support_Reads},
            $c->{Support_Records},
            $c->{Scan_Genes},
            $sv_start_range,
            $sv_end_range,
            $c->{Primary_Strand_Count},
            $c->{SA_Strand_Count},
            $c->{Cluster_Status},
        ) . "\n";
    }

    close $out_fh;
}

sub write_supporting_reads {
    my %args = @_;

    my $clusters_ref = $args{clusters};
    my $output       = $args{output};

    open my $out_fh, ">", $output
        or die "[ERROR] Cannot write supporting reads file: $output\n";

    print $out_fh join("\t", qw(
        Cluster_ID
        Cluster_Status
        Sample
        Scan_Gene
        Read_Name
        Primary_Chrom
        Primary_Start
        Primary_End
        Primary_CIGAR
        Primary_MAPQ
        Primary_Strand
        SA_Chrom
        SA_Start
        SA_End
        SA_CIGAR
        SA_MAPQ
        SA_Strand
        SV_Chrom
        SV_Start
        SV_End
        SV_Length
        SA_Tag
    )) . "\n";

    foreach my $c (@$clusters_ref) {
        foreach my $r (@{ $c->{records} }) {
            print $out_fh join("\t",
                $c->{Cluster_ID},
                $c->{Cluster_Status},
                $r->{Sample},
                $r->{Scan_Gene},
                $r->{Read_Name},
                $r->{Primary_Chrom},
                $r->{Primary_Start},
                $r->{Primary_End},
                $r->{Primary_CIGAR},
                $r->{Primary_MAPQ},
                $r->{Primary_Strand},
                $r->{SA_Chrom},
                $r->{SA_Start},
                $r->{SA_End},
                $r->{SA_CIGAR},
                $r->{SA_MAPQ},
                $r->{SA_Strand},
                $r->{SV_Chrom},
                $r->{SV_Start},
                $r->{SV_End},
                $r->{SV_Length},
                $r->{SA_Tag},
            ) . "\n";
        }
    }

    close $out_fh;
}

sub median {
    my @v = @_;

    @v = sort { $a <=> $b } @v;

    my $n = scalar(@v);
    return "NA" if $n == 0;

    if ($n % 2) {
        return $v[ int($n / 2) ];
    }
    else {
        return ($v[$n / 2 - 1] + $v[$n / 2]) / 2;
    }
}

sub int_median {
    my @v = @_;

    my $m = median(@v);
    return "NA" if $m eq "NA";

    return int($m + 0.5);
}

sub min {
    my @v = @_;

    die "[ERROR] min() received empty list\n" unless @v;

    my $m = $v[0];

    foreach my $x (@v) {
        $m = $x if $x < $m;
    }

    return $m;
}

sub max {
    my @v = @_;

    die "[ERROR] max() received empty list\n" unless @v;

    my $m = $v[0];

    foreach my $x (@v) {
        $m = $x if $x > $m;
    }

    return $m;
}

sub format_count_hash {
    my ($hash_ref) = @_;

    my @items;

    foreach my $k (sort keys %$hash_ref) {
        push @items, $k . ":" . $hash_ref->{$k};
    }

    return @items ? join(",", @items) : "NA";
}

